ewlabel{tab:datasets}{{1}{4}{Dataset statistics. BCS Range: min--max over count-curve batches. Embedding: model used for SCS/BCS; ranges are not comparable across embedding models. $^\dagger $Trigger mentions across 8{,}042 sentences}{table.caption.9}{}}

ewlabel{tab:pairwise}{{2}{6}{Pairwise SCS--confusion correlation. Confusion rate is bidirectional $C(t_i{	o }t_j) + C(t_j{	o }t_i)$ divided by gold frequency sum; CIs are percentile bootstrap ($B{=}10{,}000$). FewRel ($r = 0.187$; \S ef {sec:scs-validation}) excluded (per-instance RE format). Type-level cluster bootstrap CIs exclude zero (Few-NERD [0.069, 0.219]; MAVEN [0.081, 0.185])}{table.caption.14}{}}

ewlabel{sec:appendix_figures}{{A}{12}{Additional Figures}{appendix.A}{}}

ewlabel{tab:cross_model}{{3}{12}{Cross-model count-curve replication on Few-NERD (text-match recall). Both models show a general declining trend in recall with schema size. Per-batch correlation $r = 0.725$. Qwen3-32B values use the v2 prompt (\S ef {sec:model}) for fair cross-model comparison; the count-curve results in \S ef {sec:count_curves} use the v1 prompt, yielding higher absolute recall (0.72 vs.\ 0.64 at count${}\,=\,1$) due to over-prediction under v1}{table.caption.26}{}}

ewlabel{tab:cross_model_bcs}{{4}{12}{Cross-model BCS-controlled FewRel accuracy. High-BCS accuracy converges to $\approx $51\% regardless of model, while low-BCS accuracy reflects model capacity differences. The confusability gap ($\Delta $, in pp) is 77--87\% as large on Llama-3.1-8B as on Qwen3-32B}{table.caption.27}{}}

ewlabel{tab:cross_model_ner_null}{{5}{12}{NER batch-level BCS--F1 correlation across models. $^\dagger $Partial correlation controlling for type frequency. $^\ddagger $LLaMA-70B count\_12 shows $r{=}{-}0.42$ ($p{=}0.034$, uncorrected; Bonferroni $p{=}0.069$); pooled and count\_6 are null, consistent with sampling noise at $n{=}25$. The null is observed on three models; Gemini remains untested}{table.caption.28}{}}

ewlabel{sec:appendix_sdgd}{{B}{12}{SDGD Full Protocol and Results}{appendix.B}{}}

ewlabel{tab:error_taxonomy}{{6}{13}{Intra-batch substitution (IntraSub) and missed-entity rates by BCS bin. Spearman $ho $ computed over $n=148$ batches (NER), $n=154$ (RE), and $n=110$ (DocRE). IntraSub scales monotonically with BCS across all three datasets. DocRE missed rates decrease with BCS, indicating high-confusability errors shift from omission to substitution}{table.caption.29}{}}

ewlabel{tab:cross_model_error_taxonomy}{{7}{13}{Cross-model replication of IntraSub--BCS Spearman correlation on FewRel RE. $^\dagger $LLaMA-70B has only 20 batches with 17.4\% missed rate; the null is attributable to insufficient power rather than absence of the effect}{table.caption.30}{}}

ewlabel{tab:sdgd_results}{{8}{13}{Few-NERD extraction under decomposition modes. V1 uses union merge; v2 uses confidence-gated merge with 	exttt {min\_batch\_size=8} (reducing 8$	o $4 batches for sdgd\_zero). All decomposition modes produce lower F1 than the single-pass baseline. All modes use the v1 prompt}{table.caption.31}{}}

ewlabel{sec:appendix_routing}{{B.1}{13}{Practical Routing Strategies on RE}{subsection.B.1}{}}

ewlabel{tab:routing_strategies}{{9}{13}{Routing strategy comparison on FewRel 80-relation RE with graph-coloring sub-schema decomposition. Oracle requires gold labels. All practical (non-oracle) strategies perform below the single-pass baseline. The failure stems from constrained decoding (enum constraint), which forces confident predictions in every sub-schema: 73.4\% of instances receive positive predictions from 3--5 sub-schemas simultaneously, with per-sub-schema none-rates of only 20--40\%}{table.caption.32}{}}

ewlabel{sec:appendix_factorial}{{C}{13}{Factorial Analysis and Separability Test}{appendix.C}{}}

ewlabel{tab:tost_sensitivity}{{10}{14}{TOST sensitivity analysis across equivalence margins. The interaction effect (0.47\,pp, 90\% CI [$-$1.0, 2.0]\,pp) is bounded below 2\,pp at marginal significance ($p = 0.047$); the $\pm 3$\,pp choice does not drive the equivalence conclusion. At $\pm 1$\,pp, equivalence is inconclusive ($p = 0.278$), meaning interaction could reach approximately half the main effect magnitude}{table.caption.34}{}}

ewlabel{sec:appendix_within_pool}{{D}{15}{Within-Pool CI Details}{appendix.D}{}}

ewlabel{sec:appendix_residualized_bcs}{{E}{15}{Controlling for Centrality Confounds in MAVEN Per-Type Analysis}{appendix.E}{}}

ewlabel{tab:residualized_bcs}{{11}{15}{MAVEN per-type BCS--F1 correlation before and after controlling for centrality confounders. Raw correlations are Spearman $ho $; partial correlations are Pearson $r$ from residualized regression. Degree centrality is computed on the SCS graph at threshold 0.7. All values from experiment 	exttt {exp\_maven\_residualized\_bcs}}{table.caption.40}{}}

ewlabel{sec:appendix_partial_corr}{{E.1}{15}{Partial Correlation: Controlling for Degree Centrality}{subsection.E.1}{}}

ewlabel{tab:partial_corr}{{12}{16}{BCS--accuracy partial correlation controlling for degree centrality. FewRel shows minimal attenuation (VIF${}\,=\,1.18$, low collinearity). DocRED shows high BCS--centrality collinearity (VIF${}\,=\,50.9$, $r = 0.99$), but the partial correlation remains highly significant}{table.caption.42}{}}

